	@Test
	public void compilesBindsAndFills() throws Exception {
		JaninoKernel kernel = awaitKernel("shape-basic");
		assertNotNull(kernel);
		kernel.bind(new KernelContext(null, new long[] { 42L }, null, null));
		long[] buffer = new long[4];
		assertEquals(1, kernel.fill(buffer, 4));
		assertEquals(42L, buffer[0]);
		assertEquals(0, kernel.fill(buffer, 4));
		kernel.close();
		assertEquals(1L, LmdbNativeJaninoCodegen.COMPILATIONS.get());
	}

	@Test
	public void synchronousModeCompilesBeforeReturning() throws Exception {
		System.setProperty(SYNCHRONOUS_PROPERTY, "true");
		AtomicReference<Thread> requestThread = new AtomicReference<>();
		AtomicReference<Thread> sourceThread = new AtomicReference<>();
		CountDownLatch sourceEntered = new CountDownLatch(1);
		CountDownLatch releaseSource = new CountDownLatch(1);

		CompletableFuture<JaninoKernel> requested = CompletableFuture.supplyAsync(() -> {
			requestThread.set(Thread.currentThread());
			return LmdbNativeJaninoCodegen.kernel("shape-synchronous", KERNEL_CLASS, () -> {
				sourceThread.set(Thread.currentThread());
				sourceEntered.countDown();
				try {
					releaseSource.await();
				} catch (InterruptedException e) {
					Thread.currentThread().interrupt();
					throw new AssertionError(e);
				}
				return KERNEL_SOURCE;
			}, 1L);
		});

		assertTrue(sourceEntered.await(30, TimeUnit.SECONDS));
		try {
			assertSame(requestThread.get(), sourceThread.get(),
					"synchronous source generation must run on the requesting thread");
		} finally {
			releaseSource.countDown();
		}
		JaninoKernel kernel = requested.get(30, TimeUnit.SECONDS);
		assertNotNull(kernel);
		kernel.close();
	}

	@Test
	public void concurrentSynchronousRequestsCompileOnceAndBothAwaitTheResult() throws Exception {
		System.setProperty(SYNCHRONOUS_PROPERTY, "true");
		CountDownLatch sourceEntered = new CountDownLatch(1);
		CountDownLatch releaseSource = new CountDownLatch(1);
		AtomicInteger sourceCalls = new AtomicInteger();
		Supplier<String> source = () -> {
			sourceCalls.incrementAndGet();
			sourceEntered.countDown();
			try {
				releaseSource.await();
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
				throw new AssertionError(e);
			}
			return KERNEL_SOURCE;
		};

		CompletableFuture<JaninoKernel> first = CompletableFuture.supplyAsync(
				() -> LmdbNativeJaninoCodegen.kernel("shape-concurrent", KERNEL_CLASS, source, 1L));
		assertTrue(sourceEntered.await(30, TimeUnit.SECONDS));
		CompletableFuture<JaninoKernel> second = CompletableFuture.supplyAsync(
				() -> LmdbNativeJaninoCodegen.kernel("shape-concurrent", KERNEL_CLASS, source, 1L));
		try {
			assertThrows(TimeoutException.class, () -> second.get(1, TimeUnit.SECONDS),
					"the concurrent request must await the in-progress compilation");
		} finally {
			releaseSource.countDown();
		}
		JaninoKernel firstKernel = first.get(30, TimeUnit.SECONDS);
		JaninoKernel secondKernel = second.get(30, TimeUnit.SECONDS);
		try {
			assertNotNull(firstKernel);
			assertNotNull(secondKernel);
			assertTrue(firstKernel != secondKernel);
			assertEquals(1, sourceCalls.get());
			assertEquals(1L, LmdbNativeJaninoCodegen.COMPILATIONS.get());
		} finally {
			if (firstKernel != null) {
				firstKernel.close();
			}
			if (secondKernel != null) {
				secondKernel.close();
			}
		}
	}

